import { Router } from "express";
import applicationController from "../controllers/application.controller";
import { protect, authorize } from "../middleware/authMiddleware";
const router = Router();
router.post("/", protect, authorize("job-seeker"), applicationController.applyForJob);
router.get("/", protect, authorize("job-seeker"), applicationController.getMyApplications);
router.get("/timeline", protect, authorize("employer"), applicationController.getApplicationTimeline);
router.get("/employer", protect, authorize("employer"), applicationController.getEmployerApplications);
router.get("/stats", protect, applicationController.getApplicationStats);
router.get("/:id", protect, applicationController.getApplicationById);
router.patch("/:id/status", protect, authorize("employer"), applicationController.updateApplicationStatus);
router.patch("/:id/withdraw", protect, authorize("job-seeker"), applicationController.withdrawApplication);
router.delete("/:id", protect, authorize("admin"), applicationController.deleteApplication);
export default router;
